import{_ as l,c as e,o as i,a8 as t}from"./chunks/framework.jsZJWZJf.js";const h=JSON.parse('{"title":"《山茶文具店》","description":"","frontmatter":{},"headers":[],"relativePath":"blog/read/读后感/20220330山茶文具店.md","filePath":"blog/read/读后感/20220330山茶文具店.md","lastUpdated":1795103431000}'),r={name:"blog/read/读后感/20220330山茶文具店.md"};function _(o,a,d,n,s,c){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="《山茶文具店》" tabindex="-1">《山茶文具店》 <a class="header-anchor" href="#《山茶文具店》" aria-label="Permalink to “《山茶文具店》”">​</a></h1><h2 id="_2022-03-30-22-22-周三" tabindex="-1">2022-03-30 22:22 周三 <a class="header-anchor" href="#_2022-03-30-22-22-周三" aria-label="Permalink to “2022-03-30 22:22 周三”">​</a></h2><p>📍中国云南省昆明市官渡区矣六街道君安路</p><ul><li>今天看完了《山茶文具店》，讲代笔人雨宫鸠子的故事，以她跟上代也就是她的外婆之间的误解为线索，穿插了很多她执笔的事情。</li><li>看完之后我没有像其他读者那样有那么多的感动，或者细心的发现了书里面的目录顺序暗示着什么。只是觉得整个故事很温暖人心，知道了作为代笔人不仅仅是书信的内容，从写信的纸质，到笔，到墨水的颜色，到书写的字体到信封，到封信，到邮票的选择，每一个小细节，都充满着用心，不管是执笔写什么内容，每一个小细节都有在细细考究。</li><li>不过我很好奇，寄出去的信如此用心是跟代笔人有关，那么收信人是否有感受到这些小细节呢？整个故事描写的都很细腻，里面的形容词，对当时场景的描写都非常细致，好像我也能感受到她们吹的海风，以及吃的食物，让我对镰仓这个地方也充满想象。</li><li>她跟上代之间的误会，通过一些其他人讲述的故事，一点点被化解，鸠子对上代的误解，以及内心对她的排斥也一点一点消失，最后跟已经离世的上代和解，这个过程一点一点不经意的就化解了。最近我也会想怎么样才算跟自己和解，看到鸠子跟上代的故事，我想我明白了一点点，一点点的事情，一点点的故事，让鸠子从另外一些角度了解了上代，也了解上代对她的良苦用心。</li><li>可能我们跟自己和解也是这样吧，一点点的告诉自己不要去在意，一点点的从其他角度思考问题，一点点的打开自己的心扉让自己不再去执着。书里面描写的很多有意思的细节描写我都保存下来了，也会找个时间写在自己的小本子上。</li><li>写一下我自己还记得的里面的代笔故事 <ul><li>鸠子跟QP妹妹之间的往来（并没有把对方当做小孩子，认真对待她的每一封信，并且认真回信）</li><li>鸠子跟芭芭拉夫人（与长辈之间的友谊，有趣的邻居）</li><li>关于“字如其人”，善良的人，也有可能写出不好看的字，字不一定如其人</li><li>关于告知“她”我还好</li></ul></li><li>作为代笔人可以倾听别人的故事是一件好事，但是也要守住职业底线，也很不容易！</li></ul>',4)])])}const m=l(r,[["render",_]]);export{h as __pageData,m as default};
